    function toggleMenu() {
      var dropdown = document.getElementById('vizMenuDropdown');
      if (dropdown) dropdown.classList.toggle('open');
    }
    document.addEventListener('click', function(e) {
      if (!e.target.closest('.viz-menu')) {
        var dropdown = document.getElementById('vizMenuDropdown');
        if (dropdown) dropdown.classList.remove('open');
      }
    });
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') {
        var dropdown = document.getElementById('vizMenuDropdown');
        if (dropdown) dropdown.classList.remove('open');
      }
    });
    var currentTheme = 'dark';
    function applyTheme(t) {
      document.documentElement.className = 'theme-' + t;
      var icon = document.getElementById('themeIcon');
      var label = document.getElementById('themeLabel');
      if (icon) icon.textContent = t === 'dark' ? '🌙' : '☀️';
      if (label) label.textContent = t === 'dark' ? 'Dark' : 'Light';
      currentTheme = t;
      if (typeof onThemeChange === 'function') onThemeChange();
    }
    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
    async function downloadImage() {
      var menu = document.querySelector('.viz-menu');
      menu.style.display = 'none';
      try {
        var poster = document.getElementById('poster');
        var url = await htmlToImage.toPng(poster, { quality: 1, pixelRatio: 2, backgroundColor: '#07101e' });
        var a = document.createElement('a');
        a.href = url;
        a.download = 'worlds-most-valuable-companies-2025.png';
        a.click();
      } catch(e) { console.error('Download failed:', e); }
      menu.style.display = '';
    }
    var ChartManager = {
      charts: new Map(),
      safeInit: function(canvasId, config) {
        if (typeof Chart === 'undefined') {
          console.error('Chart.js library not loaded - check CDN inclusion');
          return null;
        }
        try {
          if (this.charts.has(canvasId)) {
            this.charts.get(canvasId).destroy();
            this.charts.delete(canvasId);
          }
          var ctx = document.getElementById(canvasId);
          if (!ctx) {
            console.error('Canvas element not found: ' + canvasId);
            return null;
          }
          if (ctx.chart) {
            ctx.chart.destroy();
            delete ctx.chart;
          }
          ctx.setAttribute('role', 'img');
          if (!ctx.getAttribute('aria-label')) ctx.setAttribute('aria-label', 'Chart visualization');
          var chart = new Chart(ctx, config);
          ctx.chart = chart;
          this.charts.set(canvasId, chart);
          return chart;
        } catch (e) {
          console.error('Chart initialization failed for ' + canvasId + ':', e);
          return null;
        }
      }
    };
    function buildValidationChart() {
      if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return; }
      ChartManager.safeInit('validationChart', {
        type: 'doughnut',
        data: { labels: ['Top 10', 'Rest'], datasets: [{ data: [25.4, 117.5], backgroundColor: ['#f4c45f', '#24324a'], borderWidth: 0 }] },
        options: { responsive: true, maintainAspectRatio: false, plugins: { tooltip: { enabled: true }, legend: { display: false } } }
      });
    }
    function onThemeChange() { buildValidationChart(); }
    window.addEventListener('load', buildValidationChart);
  </script>
