const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1200, height: 1800 }, deviceScaleFactor: 2 });
  await page.goto('file:///app/output/final_poster.html', { waitUntil: 'networkidle' });
  await page.evaluate(() => document.documentElement.className = 'theme-dark');
  await page.locator('.viz-menu').evaluate(el => el.style.display = 'none');
  const poster = page.locator('#poster');
  await poster.screenshot({ path: '/app/output/final_poster.png' });
  await browser.close();
})();
